static int preprocessor_interact1(struct object *self, unsigned int action,
	unsigned char *output_stream, unsigned int capacity,
	unsigned int *output_quantity, const struct vr *caller_context)
{
	struct em_preprocessor *members = self->members;
	struct neocc_preprocessor *state = members->state;

	*output_quantity = 0;
	if (action != NEOCC_AC1_PREPROCESSOR_BORROW &&
	    action != NEOCC_AC1_PREPROCESSOR_POP &&
	    action != NEOCC_AC1_PREPROCESSOR_RESULTS) {
		SBO_OBJECT_INTERACT1;
	}
	if (!self->ref_count || !state)
		return RN_INVALIDARG;
	if (action == NEOCC_AC1_PREPROCESSOR_RESULTS) {
		const struct neocc_preprocessor_results *results = &members->results;

		if (capacity < sizeof(results))
			return RN_INVALIDARG;
		memcpy(output_stream, &results, sizeof(results));
		*output_quantity = sizeof(results);
		return R_P;
	}
	if (action == NEOCC_AC1_PREPROCESSOR_POP) {
		struct neocc_token_string *stream = state->macro_stack;
		struct neocc_macro_pop result;

		if (capacity < sizeof(result))
			return RN_INVALIDARG;
		if (!stream)
			return RO_VAINLY;
		result.saved_line = stream->save_line_num;
		result.release = stream->alloc ? stream : NULL;
		state->macro_stack = stream->prev;
		state->macro_ptr = stream->prev_ptr;
		if (!stream->alloc)
			stream->len = stream->need_spc = 0;
		else if (stream->alloc == 2)
			stream->str = NULL;
		memcpy(output_stream, &result, sizeof(result));
		*output_quantity = sizeof(result);
		return R_P;
	}
	if (capacity < sizeof(state))
		return RN_INVALIDARG;
	memcpy(output_stream, &state, sizeof(state));
	*output_quantity = sizeof(state);
	return R_P;
}

static int preprocessor_interact2(struct object *self, unsigned int action,
	unsigned char *input_stream, unsigned int quantity,
	const struct vr *caller_context)
{
	struct em_preprocessor *members = self->members;
	struct neocc_preprocessor *state = members->state;
	struct neocc_macro_push request;
	struct neocc_token_string *stream;

	if (action == NEOCC_AC2_PREPROCESSOR_DEPENDENCY ||
	    action == NEOCC_AC2_PREPROCESSOR_LIBRARY) {
		if (!self->ref_count || !state)
			return RN_INVALIDARG;
		return list_append(action == NEOCC_AC2_PREPROCESSOR_LIBRARY ?
			&members->results.libraries : &members->results.dependencies,
			input_stream, quantity);
	}
	if (action != NEOCC_AC2_PREPROCESSOR_PUSH) {
		SBO_OBJECT_INTERACT2;
	}
	if (!self->ref_count || !state || quantity != sizeof(request))
		return RN_INVALIDARG;
	memcpy(&request, input_stream, sizeof(request));
	stream = request.stream;
	if (!stream || request.alloc < 0 || request.alloc > 2)
		return RN_INVALIDARG;
	stream->alloc = request.alloc;
	stream->prev = state->macro_stack;
	stream->prev_ptr = state->macro_ptr;
	stream->save_line_num = request.line;
	state->macro_stack = stream;
	state->macro_ptr = stream->str;
	return R_P;
}

void tog_preprocessor(struct object *object)
{
	object->open = preprocessor_open;
	object->input = preprocessor_input;
	object->output = preprocessor_output;
	object->io_put = preprocessor_io_put;
	object->interact0 = preprocessor_interact0;
	object->interact1 = preprocessor_interact1;
	object->interact2 = preprocessor_interact2;
	object->interact3 = preprocessor_interact3;
	object->close = preprocessor_close;
}

int neocc_string_vprintf(struct neocc_string *string, const char *fmt,
	va_list arguments)
{
	va_list copy;
	int length;

	va_copy(copy, arguments);
	length = vsnprintf(NULL, 0, fmt, copy);
	va_end(copy);
	if (length < 0 || string->size < 0 ||
	    length >= INT_MAX - string->size ||
	    !neocc_string_reserve(string, string->size + length + 1))
		return -1;
	va_copy(copy, arguments);
	length = vsnprintf(string->data + string->size,
		string->size_allocated - string->size, fmt, copy);
	va_end(copy);
	if (length < 0)
		return -1;
	string->size += length;
	return length;
}

int neocc_string_printf(struct neocc_string *string, const char *fmt, ...)
{
	va_list arguments;
	int length;

	va_start(arguments, fmt);
	length = neocc_string_vprintf(string, fmt, arguments);
	va_end(arguments);
	return length;
}
